# Run from project root: C:\Users\Barr. Tobi Ogunleye\Projects\lawfirm-site
$path = "app\components\Publications.tsx"

if (-not (Test-Path $path)) {
    Write-Error "Publications.tsx not found at $path -- run this from the project root."
    exit 1
}

$fullPath = Join-Path (Get-Location).Path $path

Copy-Item $fullPath "$fullPath.bak" -Force
Write-Output "Backed up existing file to $fullPath.bak"

$b64 = ""

$bytes = [System.Convert]::FromBase64String($b64)
[System.IO.File]::WriteAllBytes($fullPath, $bytes)

Write-Output "Publications.tsx replaced. Diff it, then npm run dev to check."
